    ).normalize();

    [['axial', aDir, colA], ['eq', eDir, COL_EQ]].forEach(([hk, dir, col]) => {
      const g = new THREE.Group();
      g.position.copy(cp);
      root.add(g);
      const hp = dir.clone().multiplyScalar(CH * S);
      const hm = new THREE.Mesh(geoH, atomMat(col));
      hm.position.copy(hp);
      g.add(hm);
      const hEntry = { mesh: hm, mat: hm.material, kind: hk, ci: i, base: col };
      hm.userData.entry = hEntry; entries.push(hEntry);
