  const ctrlA = midA.clone().add(new THREE.Vector3(0.28, 0, -0.35));
  const arrowA = makeArrow(startA, ctrlA, tipA, MAGENTA);

  const c5 = carbons[5];                                     // top carbon, equatorial H on the rim
  const eD5 = new THREE.Vector3(
    Math.cos(c5.th) * Math.cos(EQ_TILT), -c5.s * Math.sin(EQ_TILT), Math.sin(c5.th) * Math.cos(EQ_TILT)
  ).normalize();
  const eH = c5.pos.clone().addScaledVector(eD5, CH * S);
  const tipE = new THREE.Vector3(eH.x - 0.349 * rH * 1.02, FRONT, eH.z - 0.937 * rH * 1.02);
  const startE = tipE.clone().add(new THREE.Vector3(-1.25, 0, -1.45));
  const midE = startE.clone().add(tipE).multiplyScalar(0.5);
  const ctrlE = midE.clone().add(new THREE.Vector3(0.30, 0, -0.25));
  const arrowE = makeArrow(startE, ctrlE, tipE, BLUEARR);

  const annot = new THREE.Group();
  annot.add(arrowA); annot.add(arrowE);
  root.add(annot);

  return {
    kind, S, rC, rH, root, entries, carbons, hGroups, annot, arrowA, arrowE,
    anchorA: startA.clone().add(new THREE.Vector3(-0.60, 0, -0.38)),
    anchorE: startE.clone().add(new THREE.Vector3(-0.52, 0, -0.55)),
    presence: 0, presenceT: 0, scale: 1, scaleT: 1, x: 0, xT: 0
  };
}

const sf = buildModel('sf');
const bs = buildModel('bs');
const models = [sf, bs];

