// ─── ELEMENT SPEC ────────────────────────────────────────────────────────────
// ring carbon (space-filling) → SphereGeometry(1.70*0.88)  MeshPhysicalMaterial #4B5053
// axial H     (space-filling) → SphereGeometry(1.20*0.88)  #B8352A
// equatorial H(space-filling) → SphereGeometry(1.20*0.88)  #46A8DC
// ring carbon (ball&stick)    → SphereGeometry(0.36)       #4B5053
// axial H     (ball&stick)    → SphereGeometry(0.24)       #C0392B
// equatorial H(ball&stick)    → SphereGeometry(0.24)       #46A8DC
// C–C + C–H rods (ball&stick) → CylinderGeometry(0.075)    #C6D4DC
// axial arrow       → TubeGeometry(QuadraticBezierCurve3) + ConeGeometry tip, #E0218A
// equatorial arrow  → TubeGeometry(QuadraticBezierCurve3) + ConeGeometry tip, #1C9AD6
// labels            → addLabel('Axial' #E0218A), addLabel('Equatorial' #1C9AD6)
// lighting          → AmbientLight + key DirectionalLight upper-left + fill + rim
// ─────────────────────────────────────────────────────────────────────────────

const DEG = Math.PI / 180;
const RING_R = 1.46, PUCK = 0.25, CH = 1.09, EQ_TILT = 19.5 * DEG;
const COL_C = 0x4B5053, COL_EQ = 0x46A8DC, COL_ROD = 0xC6D4DC;
const MAGENTA = 0xE0218A, BLUEARR = 0x1C9AD6;

/* ── lighting ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.75);
keyLight.position.set(-6, 9, -6);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xdbeaf5, 0.65);
fillLight.position.set(5, -3, 6);
scene.add(fillLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.35);
rimLight.position.set(4, 3, 7);
scene.add(rimLight);

/* ── helpers ──────────────────────────────────────────────────────────────── */
function atomMat(hex) {
  return new THREE.MeshPhysicalMaterial({
    color: hex, roughness: 0.24, metalness: 0.04,
    clearcoat: 0.9, clearcoatRoughness: 0.12,
    transparent: false, opacity: 1
  });
}
function makeRod(a, b, r, hex) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(r, r, len, 18, 1),
    new THREE.MeshPhysicalMaterial({ color: hex, roughness: 0.42, metalness: 0.02, clearcoat: 0.4, transparent: false, opacity: 1 })
  );
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
function makeArrow(start, ctrl, tip, hex) {
  const g = new THREE.Group();
  const dir = tip.clone().sub(ctrl).normalize();
  const shaftEnd = tip.clone().addScaledVector(dir, -0.34);
  const curve = new THREE.QuadraticBezierCurve3(start, ctrl, shaftEnd);
  const mat = new THREE.MeshBasicMaterial({ color: hex });
  g.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 36, 0.055, 10, false), mat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.15, 0.40, 22), mat);
  cone.position.copy(tip).addScaledVector(dir, -0.20);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  return g;
}

/* ── molecule builder ─────────────────────────────────────────────────────── */
function buildModel(kind) {
  const S = (kind === 'sf') ? 0.88 : 1.0;
  const rC = (kind === 'sf' ? 1.70 : 0.36) * S;
  const rH = (kind === 'sf' ? 1.20 : 0.24) * S;
  const colA = (kind === 'sf') ? 0xB8352A : 0xC0392B;
  const geoC = new THREE.SphereGeometry(rC, 48, 32);
  const geoH = new THREE.SphereGeometry(rH, 40, 28);

  const root = new THREE.Group();
  scene.add(root);
  const entries = [], carbons = [], hGroups = [];

  for (let i = 0; i < 6; i++) {
    const th = (-30 + 60 * i) * DEG;
    const s = (i % 2 === 0) ? 1 : -1;                      // pucker: even up, odd down
    const cp = new THREE.Vector3(RING_R * Math.cos(th), s * PUCK, RING_R * Math.sin(th)).multiplyScalar(S);

    const cm = new THREE.Mesh(geoC, atomMat(COL_C));
    cm.position.copy(cp);
    root.add(cm);
    const cEntry = { mesh: cm, mat: cm.material, kind: 'C', ci: i, base: COL_C };
    cm.userData.entry = cEntry; entries.push(cEntry);
    carbons.push({ i, pos: cp, s, th, mesh: cm });

    const aDir = new THREE.Vector3(0, s, 0);
    const eDir = new THREE.Vector3(
      Math.cos(th) * Math.cos(EQ_TILT), -s * Math.sin(EQ_TILT), Math.sin(th) * Math.cos(EQ_TILT)
    ).normalize();

    [['axial', aDir, colA], ['eq', eDir, COL_EQ]].forEach(([hk, dir, col]) => {
      const g = new THREE.Group();
      g.position.copy(cp);
      root.add(g);
      const hp = dir.clone().multiplyScalar(CH * S);
      const hm = new THREE.Mesh(geoH, atomMat(col));
      hm.position.copy(hp);
      g.add(hm);
      const hEntry = { mesh: hm, mat: hm.material, kind: hk, ci: i, base: col };
      hm.userData.entry = hEntry; entries.push(hEntry);
      if (kind === 'bs') {
        const rod = makeRod(new THREE.Vector3(0, 0, 0), hp.clone(), 0.075, COL_ROD);
        g.add(rod);
        entries.push({ mesh: rod, mat: rod.material, kind: hk, ci: i, isRod: true, base: COL_ROD });
      }
      hGroups.push({ group: g, kind: hk, ci: i });
    });
  }

  if (kind === 'bs') {
    for (let i = 0; i < 6; i++) {
      const a = carbons[i].pos, b = carbons[(i + 1) % 6].pos;
      const rod = makeRod(a.clone(), b.clone(), 0.085, COL_ROD);
      root.add(rod);
      entries.push({ mesh: rod, mat: rod.material, kind: 'bond', ci: [i, (i + 1) % 6], isRod: true, base: COL_ROD });
    }
  }

  /* annotations (arrows + label anchors), parented to the model so they scale with it */
  const FRONT = 3.0;
  const c4 = carbons[4];                                     // upper-left carbon, axial toward viewer
  const aH = c4.pos.clone().add(new THREE.Vector3(0, c4.s * CH * S, 0));
  const tipA = new THREE.Vector3(aH.x - 0.707 * rH * 1.02, FRONT, aH.z - 0.707 * rH * 1.02);
  const startA = tipA.clone().add(new THREE.Vector3(-1.9, 0, -1.5));
  const midA = startA.clone().add(tipA).multiplyScalar(0.5);
  const ctrlA = midA.clone().add(new THREE.Vector3(0.28, 0, -0.35));
  const arrowA = makeArrow(startA, ctrlA, tipA, MAGENTA);

  const c5 = carbons[5];                                     // top carbon, equatorial H on the rim
  const eD5 = new THREE.Vector3(
    Math.cos(c5.th) * Math.cos(EQ_TILT), -c5.s * Math.sin(EQ_TILT), Math.sin(c5.th) * Math.cos(EQ_TILT)
  ).normalize();
  const eH = c5.pos.clone().addScaledVector(eD5, CH * S);
  const tipE = new THREE.Vector3(eH.x - 0.349 * rH * 1.02, FRONT, eH.z - 0.937 * rH * 1.02);
  const startE = tipE.clone().add(new THREE.Vector3(-1.25, 0, -1.45));
  const midE = startE.clone().add(tipE).multiplyScalar(0.5);
  const ctrlE = midE.clone().add(new THREE.Vector3(0.30, 0, -0.25));
  const arrowE = makeArrow(startE, ctrlE, tipE, BLUEARR);

  const annot = new THREE.Group();
  annot.add(arrowA); annot.add(arrowE);
  root.add(annot);

  return {
    kind, S, rC, rH, root, entries, carbons, hGroups, annot, arrowA, arrowE,
    anchorA: startA.clone().add(new THREE.Vector3(-0.60, 0, -0.38)),
    anchorE: startE.clone().add(new THREE.Vector3(-0.52, 0, -0.55)),
    presence: 0, presenceT: 0, scale: 1, scaleT: 1, x: 0, xT: 0
  };
}

const sf = buildModel('sf');
const bs = buildModel('bs');
const models = [sf, bs];

/* ── state ────────────────────────────────────────────────────────────────── */
