  { title: 'Open up the model', model: 'bs', filter: 'both',
    text: 'The ball-and-stick view shows the same arrangement with the bonds visible. Click any carbon: its red axial and blue equatorial hydrogen light up together — both belong to that one carbon.' },
  { title: 'Compare the two models', model: 'both', filter: 'both',
    text: 'Side by side, the packed and open representations match position for position. Orbit to a side-on view to watch the axial bonds line up parallel to the ring axis while the equatorial bonds point out around the belt.' }
];
let step = 0, playTimer = null;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i) {
  step = (i % STEPS.length + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  setModel(s.model);
  setFilter(s.filter);
  stepTitle.textContent = (step + 1) + '/' + STEPS.length + '. ' + s.title;
  stepText.textContent = s.text;
}
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('btnPlay').textContent = '▶ Play'; }
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(step - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(step + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  if (playTimer) { stopPlay(); return; }
  e.target.textContent = '❚❚ Pause';
  playTimer = setInterval(() => goToStep(step + 1), 5200);
  goToStep(step + 1);
});

goToStep(0);
applySelection(null);
updateState(true);

/* ── state loop (separate from the scaffold render loop) ──────────────────── */
(function stateTick() {
  requestAnimationFrame(stateTick);
  updateState(false);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

