}
function makeRod(a, b, r, hex) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(r, r, len, 18, 1),
    new THREE.MeshPhysicalMaterial({ color: hex, roughness: 0.42, metalness: 0.02, clearcoat: 0.4, transparent: false, opacity: 1 })
  );
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
function makeArrow(start, ctrl, tip, hex) {
  const g = new THREE.Group();
  const dir = tip.clone().sub(ctrl).normalize();
  const shaftEnd = tip.clone().addScaledVector(dir, -0.40);
  const curve = new THREE.QuadraticBezierCurve3(start, ctrl, shaftEnd);
  const mat = new THREE.MeshBasicMaterial({ color: hex });
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 40, 0.070, 12, false), mat);
  g.add(tube);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.19, 0.46, 24), mat);
  cone.position.copy(tip).addScaledVector(dir, -0.23);   // apex sits exactly on `tip`
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  g.userData.parts = [tube, cone];
  return g;
}
// screen-plane point: screen-right = +X, screen-up = -Z (see camera below)
function sp(sx, sy) { return new THREE.Vector3(sx, FRONT, -sy); }
// push a world point out to the FRONT plane along the camera ray (keeps screen position)
function toFrontPlane(p) {
  const c = camera.position;
  const t = (FRONT - c.y) / (p.y - c.y);
  return new THREE.Vector3(c.x + (p.x - c.x) * t, FRONT, c.z + (p.z - c.z) * t);
}

/* ── molecule builder ─────────────────────────────────────────────────────── */
function buildModel(kind) {
  const isSF = (kind === 'sf');
  const S = isSF ? 0.88 : 1.0;
  const rC = (isSF ? 1.75 : 0.36) * S;
  const rHax = (isSF ? 1.16 : 0.24) * S;
  const rHeq = (isSF ? 1.28 : 0.26) * S;
  const colA = isSF ? 0xB8352A : 0xC0392B;
  const geoC = new THREE.SphereGeometry(rC, 48, 32);
  const geoHa = new THREE.SphereGeometry(rHax, 40, 28);
  const geoHe = new THREE.SphereGeometry(rHeq, 40, 28);

  const root = new THREE.Group();
  scene.add(root);
  const entries = [], carbons = [], hGroups = [];

  for (let i = 0; i < 6; i++) {
    const th = (-30 + 60 * i) * DEG;
    const s = (i % 2 === 0) ? 1 : -1;                      // pucker: even up, odd down
    const cp = new THREE.Vector3(RING_R * Math.cos(th), s * PUCK, RING_R * Math.sin(th)).multiplyScalar(S);

    const cm = new THREE.Mesh(geoC, atomMat(COL_C, true));
    cm.position.copy(cp);
    root.add(cm);
    const cEntry = { mesh: cm, mat: cm.material, kind: 'C', ci: i, base: COL_C };
    cm.userData.entry = cEntry; entries.push(cEntry);
    carbons.push({ i, pos: cp, s, th, mesh: cm });

    const aDir = new THREE.Vector3(0, s, 0);
    const eDir = new THREE.Vector3(
      Math.cos(th) * Math.cos(EQ_TILT), -s * Math.sin(EQ_TILT), Math.sin(th) * Math.cos(EQ_TILT)
    ).normalize();

    [['axial', aDir, colA, geoHa], ['eq', eDir, COL_EQ, geoHe]].forEach(([hk, dir, col, geo]) => {
      const g = new THREE.Group();
      g.position.copy(cp);
      root.add(g);
      const hp = dir.clone().multiplyScalar(CH * S);
      const hm = new THREE.Mesh(geo, atomMat(col, false));
      hm.position.copy(hp);
      g.add(hm);
      const hEntry = { mesh: hm, mat: hm.material, kind: hk, ci: i, base: col };
      hm.userData.entry = hEntry; entries.push(hEntry);
      if (!isSF) {
        const rod = makeRod(new THREE.Vector3(0, 0, 0), hp.clone(), 0.075, COL_ROD);
        g.add(rod);
        entries.push({ mesh: rod, mat: rod.material, kind: hk, ci: i, isRod: true, base: COL_ROD });
      }
      hGroups.push({ group: g, kind: hk, ci: i });
    });
  }

  if (!isSF) {
    for (let i = 0; i < 6; i++) {
      const a = carbons[i].pos, b = carbons[(i + 1) % 6].pos;
      const rod = makeRod(a.clone(), b.clone(), 0.085, COL_ROD);
      root.add(rod);
      entries.push({ mesh: rod, mat: rod.material, kind: 'bond', ci: [i, (i + 1) % 6], isRod: true, base: COL_ROD });
    }
  }

  const annot = new THREE.Group();
  root.add(annot);

  return {
    kind, S, rC, rHax, rHeq, root, entries, carbons, hGroups,
    annot, arrowA: null, arrowE: null, annEntries: [],
    anchorA: sp(0, 0), anchorE: sp(0, 0),
    presence: 0, presenceT: 0, scale: 1, scaleT: 1, x: 0, xT: 0
  };
}

const sf = buildModel('sf');
const bs = buildModel('bs');
const models = [sf, bs];

/* ── state ────────────────────────────────────────────────────────────────── */
let modelMode = 'sf';          // 'sf' | 'bs' | 'both'
let hFilter = 'both';          // 'ax' | 'eq' | 'both'
let axT = 1, eqT = 1, axFade = 1, eqFade = 1;
let selected = null;

function setModel(m) {
  modelMode = m;
  const side = (m === 'both');
  sf.presenceT = (m === 'sf' || side) ? 1 : 0;
  bs.presenceT = (m === 'bs' || side) ? 1 : 0;
  const base = side ? 0.62 : 1.0;
  sf.scaleT = base * (sf.presenceT ? 1 : 0.55);
  bs.scaleT = base * (bs.presenceT ? 1 : 0.55);
  sf.xT = side ? -4.6 * base : 0;
  bs.xT = side ? 4.6 * base : 0;
  syncButtons();
}
function setFilter(f) {
  hFilter = f;
  axT = (f === 'eq') ? 0 : 1;
  eqT = (f === 'ax') ? 0 : 1;
  syncButtons();
}

/* initial pose so scene bounds are right when the camera is fitted */
sf.presence = sf.presenceT = 1; sf.scale = sf.scaleT = 1; sf.x = sf.xT = 0;
bs.presence = bs.presenceT = 0; bs.scale = bs.scaleT = 0.55; bs.x = bs.xT = 0;
bs.root.visible = false;
bs.root.scale.setScalar(0.55);

/* ── camera (after geometry, before callouts) ─────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 90, elevationDeg: 88.5, rollDeg: 0,
  heightFraction: 0.62,
  target: [0, 0, 0]
});
document.getElementById('btnReset').style.display = '';

/* ── callout arrows (need the camera, so built here) ──────────────────────── */
function arrowFromScreenTail(tailSx, tailSy, tip3d, bulge, color) {
  const tail = sp(tailSx, tailSy);
  const tipSx = tip3d.x, tipSy = -tip3d.z;
  const dx = tipSx - tailSx, dy = tipSy - tailSy;
  const L = Math.hypot(dx, dy) || 1;
  const px = -dy / L, py = dx / L;                       // perpendicular, bulges up-right
  const ctrl = sp((tailSx + tipSx) / 2 + px * bulge, (tailSy + tipSy) / 2 + py * bulge);
  return makeArrow(tail, ctrl, tip3d, color);
}

function buildAnnotations(m) {
  const S = m.S;

  // AXIAL target: carbon 4 (upper-left on screen), axial H pointing toward the viewer.
  const c4 = m.carbons[4];
  const aC = c4.pos.clone().add(new THREE.Vector3(0, c4.s * CH * S, 0));
  const nA = new THREE.Vector3(-0.60, 0.50, -0.60).normalize();          // upper-left face of sphere
  const tipA = toFrontPlane(aC.clone().addScaledVector(nA, m.rHax * 0.99));
  const arrowA = arrowFromScreenTail(-3.95, 2.30, tipA, 0.50, MAGENTA);

  // EQUATORIAL target: carbon 5, its equatorial H is the TOP blue sphere on the rim.
  const c5 = m.carbons[5];
  const eD5 = new THREE.Vector3(
    Math.cos(c5.th) * Math.cos(EQ_TILT), -c5.s * Math.sin(EQ_TILT), Math.sin(c5.th) * Math.cos(EQ_TILT)
  ).normalize();
  const eC = c5.pos.clone().addScaledVector(eD5, CH * S);
  const nE = new THREE.Vector3(-0.55, 0.45, -0.70).normalize();          // upper-left face of sphere
  const tipE = toFrontPlane(eC.clone().addScaledVector(nE, m.rHeq * 0.99));
  const arrowE = arrowFromScreenTail(-3.05, 4.30, tipE, 0.55, BLUEARR);

  m.annot.add(arrowA); m.annot.add(arrowE);
  m.arrowA = arrowA; m.arrowE = arrowE;
  m.anchorA = sp(-4.90, 2.55);
  m.anchorE = sp(-4.35, 4.55);

  m.annEntries = [];
  arrowA.userData.parts.forEach(p => {
    const e = { mesh: p, kind: 'annA' }; p.userData.entry = e; m.annEntries.push(e);
  });
  arrowE.userData.parts.forEach(p => {
    const e = { mesh: p, kind: 'annE' }; p.userData.entry = e; m.annEntries.push(e);
  });
}
buildAnnotations(sf);
buildAnnotations(bs);

/* ── labels ───────────────────────────────────────────────────────────────── */
const labEq = addLabel('Equatorial', new THREE.Vector3(0, 0, 0), { color: '#1C9AD6', fontSize: '16px' });
const labAx = addLabel('Axial', new THREE.Vector3(0, 0, 0), { color: '#E0218A', fontSize: '16px' });

function placeLabel(entry, model, anchor, visible, px) {
  entry.pos.set(anchor.x * model.scale + model.x, anchor.y * model.scale, anchor.z * model.scale);
  entry.div.style.visibility = visible ? 'visible' : 'hidden';
  const dist = Math.max(camera.position.distanceTo(entry.pos), 1e-3);
  const s = Math.max(0.15, Math.min(6, 8 / dist));
  const fs = Math.round(px / s);
  if (entry.div.__fs !== fs) { entry.div.style.fontSize = fs + 'px'; entry.div.__fs = fs; }
}

/* ── picking (hover + click select) ───────────────────────────────────────── */
const pickRay = new THREE.Raycaster();
const pickPt = new THREE.Vector2();
const _tmp = new THREE.Vector3();
function pickEntry(ev) {
  const r = renderer.domElement.getBoundingClientRect();
  pickPt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  pickPt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  pickRay.setFromCamera(pickPt, camera);
  const targets = [];
  for (const m of models) {
    if (m.presence < 0.5) continue;
    if (m.annot.visible) for (const e of m.annEntries) targets.push(e.mesh);
    for (const e of m.entries) {
      if (e.isRod) continue;
      if (e.kind === 'axial' && axFade < 0.35) continue;
      if (e.kind === 'eq' && eqFade < 0.35) continue;
      targets.push(e.mesh);
    }
  }
  if (!targets.length) return null;
  const hits = pickRay.intersectObjects(targets, false);
  return hits.length ? hits[0].object.userData.entry : null;
}
function entryText(e) {
  if (e.kind === 'annA') return 'Axial position — parallel to the ring axis';
  if (e.kind === 'annE') return 'Equatorial position — out around the ring belt';
  const n = e.ci + 1;
  if (e.kind === 'C') return 'Ring carbon C' + n + ' — click to highlight its H pair';
  if (e.kind === 'axial') return 'Axial H on C' + n + ' — parallel to the ring axis';
  return 'Equatorial H on C' + n + ' — splayed out around the belt';
}
const selInfo = document.getElementById('selInfo');
function applySelection(ci) {
  selected = ci;
  if (ci === null) {
    selInfo.textContent = 'None — click any atom in the figure to light up one carbon with its own axial (red) and equatorial (blue) hydrogen.';
  } else {
    const up = (ci % 2 === 0);
    selInfo.innerHTML = '<b>C' + (ci + 1) + '</b> (' + (up ? 'up-puckered' : 'down-puckered') +
      '): its axial H points ' + (up ? 'up, toward you' : 'down, away from you') +
      ', its equatorial H splays outward and tilts slightly ' + (up ? 'down' : 'up') + '.';
  }
}
renderer.domElement.addEventListener('pointermove', (ev) => {
  const e = pickEntry(ev);
  if (e) { renderer.domElement.style.cursor = 'pointer'; showTooltip(entryText(e), ev); }
  else { renderer.domElement.style.cursor = 'grab'; hideTooltip(); }
});
renderer.domElement.addEventListener('click', (ev) => {
  const e = pickEntry(ev);
  if (!e) { applySelection(null); hidePopup(); return; }
  if (e.kind === 'annA') {
    showPopup('Axial hydrogens',
      'The six axial C–H bonds run exactly parallel to the ring\'s three-fold axis — the direction you are looking down. Three point up out of the page and three point down behind it, alternating carbon by carbon. In the space-filling model they read as the red spheres crowded toward the centre of the disc.');
    return;
  }
  if (e.kind === 'annE') {
    showPopup('Equatorial hydrogens',
      'The six equatorial C–H bonds point outward around the belt of the ring, tilted only about 19.5° away from the mean plane — up on the down-puckered carbons and down on the up-puckered ones. They form the big blue rim of the space-filling disc.');
    return;
  }
  applySelection(e.ci);
  const up = (e.ci % 2 === 0);
  showPopup('Carbon C' + (e.ci + 1) + ': one axial + one equatorial H',
    'This ring carbon is ' + (up ? 'puckered up' : 'puckered down') + '. Its red axial hydrogen runs exactly parallel to the ring axis (' +
    (up ? 'upward' : 'downward') + '), while its blue equatorial hydrogen points outward around the ring belt, tilted about 19.5° ' +
    (up ? 'downward' : 'upward') + '. Every one of the six carbons carries exactly one of each — so each face of the chair bears three axial and three equatorial hydrogens, alternating.');
});
document.getElementById('clearSel').addEventListener('click', () => { applySelection(null); hidePopup(); });

/* ── per-frame state update ───────────────────────────────────────────────── */
function related(e, sel) {
  if (sel === null) return true;
  return Array.isArray(e.ci) ? e.ci.indexOf(sel) >= 0 : e.ci === sel;
}
function updateState(instant) {
  const k = instant ? 1 : 0.13;
  axFade += (axT - axFade) * k;
  eqFade += (eqT - eqFade) * k;

  for (const m of models) {
    m.presence += (m.presenceT - m.presence) * k;
    m.scale += (m.scaleT - m.scale) * k;
    m.x += (m.xT - m.x) * k;
    m.root.position.x = m.x;
    m.root.scale.setScalar(Math.max(0.001, m.scale));
    m.root.visible = m.presence > 0.012;

    for (const hg of m.hGroups) {
      const f = (hg.kind === 'axial') ? axFade : eqFade;
      hg.group.scale.setScalar(Math.max(0.0001, f));
    }
    for (const e of m.entries) {
      const f = (e.kind === 'axial') ? axFade : (e.kind === 'eq') ? eqFade : 1;
      const dim = related(e, selected) ? 1 : 0.32;
      const o = m.presence * f * dim;
      const mat = e.mat;
      mat.opacity = o;
      const tr = o < 0.995;
      if (mat.transparent !== tr) { mat.transparent = tr; mat.needsUpdate = true; }
      mat.depthWrite = o > 0.55;
      if (mat.emissive) {
        const hot = (selected !== null) && related(e, selected) && !e.isRod;
        if (hot) { mat.emissive.setHex(e.base); mat.emissiveIntensity = 0.42; }
        else { mat.emissive.setHex(0x000000); mat.emissiveIntensity = 1; }
      }
    }
  }

  // callouts follow the leftmost visible model and fade out when tilted away
  const annModel = (sf.presence > 0.5) ? sf : bs;
  _tmp.copy(camera.position).sub(controls.target).normalize();
  const tilt = Math.acos(Math.min(1, Math.abs(_tmp.y))) / DEG;
  const show = tilt < 35;
  for (const m of models) {
    const on = (m === annModel) && show && m.presence > 0.5;
    m.annot.visible = on;
    m.arrowA.visible = on && axT > 0.5;
    m.arrowE.visible = on && eqT > 0.5;
  }
  placeLabel(labAx, annModel, annModel.anchorA, show && annModel.presence > 0.5 && axT > 0.5, 16);
  placeLabel(labEq, annModel, annModel.anchorE, show && annModel.presence > 0.5 && eqT > 0.5, 16);
}

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const modelBtns = Array.from(document.querySelectorAll('#modelBtns button'));
const hBtns = Array.from(document.querySelectorAll('#hBtns button'));
function syncButtons() {
  modelBtns.forEach(b => b.classList.toggle('active', b.dataset.m === modelMode));
  hBtns.forEach(b => b.classList.toggle('active', b.dataset.h === hFilter));
}

/* subtle hint that a ball-and-stick companion model exists */
const hintEl = document.getElementById('modelHint');
const bsBtn = document.querySelector('#modelBtns button[data-m="bs"]');
let hintOn = true, hintT0 = performance.now();
function hintTick() {
  if (!hintOn) return;
  const q = 0.5 + 0.5 * Math.sin((performance.now() - hintT0) / 400);
  bsBtn.style.boxShadow = '0 0 0 ' + (1 + 2.4 * q).toFixed(1) + 'px rgba(90,171,240,' + (0.22 + 0.38 * q).toFixed(2) + ')';
  requestAnimationFrame(hintTick);
}
function killHint() {
  if (!hintOn) return;
  hintOn = false;
  bsBtn.style.boxShadow = 'none';
  if (hintEl) hintEl.style.display = 'none';
}
hintTick();

modelBtns.forEach(b => b.addEventListener('click', () => { stopPlay(); killHint(); setModel(b.dataset.m); }));
hBtns.forEach(b => b.addEventListener('click', () => { stopPlay(); setFilter(b.dataset.h); }));

/* ── demo steps ───────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Looking down the ring axis', model: 'sf', filter: 'both',
    text: 'The space-filling model seen straight down the chair\'s axis: a dark gray carbon core, red axial hydrogens toward the centre of the disc and big blue equatorial hydrogens around the rim, alternating as you travel around the ring. A matching ball-and-stick companion is waiting under the Model buttons — step ahead (or click it) to open the molecule up.' },
  { title: 'Axial hydrogens only', model: 'sf', filter: 'ax',
    text: 'Hiding the blue hydrogens leaves six red axial hydrogens — three pointing up toward you and three pointing down away from you, strictly alternating around the six carbons.' },
  { title: 'Equatorial hydrogens only', model: 'sf', filter: 'eq',
    text: 'Now only the blue equatorial hydrogens remain, six of them fanning outward around the rim — again three tilted slightly up and three slightly down, alternating.' },
  { title: 'Open up the model', model: 'bs', filter: 'both',
    text: 'The ball-and-stick view shows the same arrangement with the bonds visible. Click any carbon: its red axial and blue equatorial hydrogen light up together — both belong to that one carbon.' },
  { title: 'Compare the two models', model: 'both', filter: 'both',
    text: 'Side by side, exactly as in the printed figure: the packed and open representations match position for position. Orbit to a side-on view to watch the axial bonds line up parallel to the ring axis while the equatorial bonds point out around the belt.' }
];
let step = 0, playTimer = null;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i) {
  step = (i % STEPS.length + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  if (s.model !== 'sf') killHint();
  setModel(s.model);
  setFilter(s.filter);
  stepTitle.textContent = (step + 1) + '/' + STEPS.length + '. ' + s.title;
  stepText.textContent = s.text;
}
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('btnPlay').textContent = '▶ Play'; }
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(step - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(step + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  if (playTimer) { stopPlay(); return; }
  e.target.textContent = '❚❚ Pause';
  playTimer = setInterval(() => goToStep(step + 1), 5200);
  goToStep(step + 1);
});

goToStep(0);
applySelection(null);
updateState(true);

/* ── state loop (separate from the scaffold render loop) ──────────────────── */
(function stateTick() {
  requestAnimationFrame(stateTick);
  updateState(false);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
CONTEXT FROM TEXTBOOK:
This figure looks straight down the axis of a chair-form cyclohexane ring in two matched models that color-code the two kinds of hydrogen position. On the left is a space-filling model: a compact dark gray core of ring carbons is surrounded by six large red spheres and six large blue spheres packed against one another, the red ones sitting toward the center of the disc and the blue ones fanning outward around the rim, the two colors alternating as the eye travels around the ring. A magenta arrow at the upper left points to a red sphere and is labeled "Axial"; a blue arrow at the top points to a blue sphere and is labeled "Equatorial". On the right the same view appears as a ball-and-stick model, the six dark gray carbons forming a hexagonal outline, with red spheres projecting from alternating carbons and blue spheres held outward from every carbon on thin pale rods. Separating the two positions by color rather than by perspective lets the reader count them directly, establishing that each ring carbon bears exactly one axial and one equatorial hydrogen and that each face carries three of each in alternating order.

PROJECTION TYPE: perspective
Use the scaffold's true perspective projection after building all geometry. Use this only when the source has real vanishing-point convergence or distance-based size shrinkage; then depth should visibly affect apparent size.

ELEMENTS TO RECREATE IN 3D:
  - Chair-conformation cyclohexane ring of six dark-gray carbon atoms (alternating up/down puckering)
  - Six axial hydrogens, red, one per carbon, pointing parallel to the ring's C3 axis (three up, three down, alternating)
  - Six equatorial hydrogens, blue, one per carbon, splayed outward roughly in the ring plane
  - Space-filling (CPK) model panel: overlapping van der Waals spheres — compact dark-gray carbon core, red spheres clustered toward the disc center, large blue spheres fanning around the rim, red/blue alternating around the ring
  - Ball-and-stick model panel: small dark-gray carbon spheres forming a hexagonal outline, thin pale-gray/blue rods for C–C ring bonds and C–H bonds, red spheres on alternating carbons (axial, projecting toward viewer/away), blue spheres held outward from every carbon
  - Magenta arrow from upper-left pointing at a red sphere, with magenta text label 'Axial'
  - Blue arrow from top pointing at a blue rim sphere, with blue text label 'Equatorial'
  - Neutral white background, two side-by-side panels (space-filling left, ball-and-stick right)

GEOMETRY NOTES (world-space scale, color palette, and any formula/value needed for correctness — build to these so sizes, zoom, and colors match the source; do not guess dimensions the notes already specify):
