// @FIGURE_CODE_BEGIN
// ─── ELEMENT SPEC ────────────────────────────────────────────────────────────
// ring carbon (space-filling) → SphereGeometry(1.70*0.88)  MeshPhysicalMaterial #4B5053 (matte core)
// axial H     (space-filling) → SphereGeometry(1.20*0.88)  #B8352A  glossy  (vdW H = same as eq)
// equatorial H(space-filling) → SphereGeometry(1.20*0.88)  #46A8DC  glossy  (vdW H = same as ax)
// ring carbon (ball&stick)    → SphereGeometry(0.36)       #4B5053
// axial H     (ball&stick)    → SphereGeometry(0.24)       #C0392B
// equatorial H(ball&stick)    → SphereGeometry(0.24)       #46A8DC
// C–C + C–H rods (ball&stick) → CylinderGeometry(0.085/0.075) #C6D4DC
// axial arrow      → Tube(QuadraticBezierCurve3)+Cone tip on UPPER-LEFT red sphere, #E0218A
// equatorial arrow → Tube(QuadraticBezierCurve3)+Cone tip on TOP blue rim sphere, #1C9AD6
// labels           → 'Equatorial' (#1C9AD6, top-left), 'Axial' (#E0218A, below it, left)
// layout           → side-by-side default: SF at x=-4.6, BS at x=+4.6 (source two-panel figure)
// lighting         → AmbientLight + key DirectionalLight upper-left + fill + rim
// ─────────────────────────────────────────────────────────────────────────────

const DEG = Math.PI / 180;
const RING_R = 1.46, PUCK = 0.25, CH = 1.09, EQ_TILT = 19.5 * DEG;
const COL_C = 0x4B5053, COL_EQ = 0x46A8DC, COL_ROD = 0xC6D4DC;
const MAGENTA = 0xE0218A, BLUEARR = 0x1C9AD6;
const FRONT = 2.75;                 // world-Y plane the callouts live on (toward camera)
const PANEL_X = 4.6;                // side-by-side panel offset
const SF_EXT = 3.30, BS_EXT = 2.85; // on-screen half-extent of each model

/* ── lighting ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.58));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.72);
keyLight.position.set(-6, 9, -6);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xdbeaf5, 0.62);
fillLight.position.set(5, -3, 6);
scene.add(fillLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.30);
rimLight.position.set(4, 3, 7);
scene.add(rimLight);

/* ── helpers ──────────────────────────────────────────────────────────────── */
function atomMat(hex, matte) {
  return new THREE.MeshPhysicalMaterial({
    color: hex,
    roughness: matte ? 0.42 : 0.20,
    metalness: 0.03,
    clearcoat: matte ? 0.32 : 0.95,
    clearcoatRoughness: matte ? 0.38 : 0.08,
    transparent: false, opacity: 1
  });
}
function makeRod(a, b, r, hex) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(r, r, len, 18, 1),
    new THREE.MeshPhysicalMaterial({ color: hex, roughness: 0.42, metalness: 0.02, clearcoat: 0.4, transparent: false, opacity: 1 })
  );
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
function makeArrow(start, ctrl, tip, hex) {
  const g = new THREE.Group();
  const dir = tip.clone().sub(ctrl).normalize();
  const shaftEnd = tip.clone().addScaledVector(dir, -0.40);
  const curve = new THREE.QuadraticBezierCurve3(start, ctrl, shaftEnd);
  const mat = new THREE.MeshBasicMaterial({ color: hex });
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 40, 0.070, 12, false), mat);
  g.add(tube);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.19, 0.46, 24), mat);
  cone.position.copy(tip).addScaledVector(dir, -0.23);   // apex sits exactly on `tip`
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  g.userData.parts = [tube, cone];
  return g;
}
// screen-plane point: screen-right = +X, screen-up = -Z (see camera below)
function sp(sx, sy) { return new THREE.Vector3(sx, FRONT, -sy); }
// push a world point out to the FRONT plane along the camera ray (keeps screen position)
function toFrontPlane(p) {
  const c = camera.position;
  const denom = (p.y - c.y);
  const t = Math.abs(denom) < 1e-6 ? 1 : (FRONT - c.y) / denom;
  return new THREE.Vector3(c.x + (p.x - c.x) * t, FRONT, c.z + (p.z - c.z) * t);
}

/* ── molecule builder ─────────────────────────────────────────────────────── */
function buildModel(kind) {
  const isSF = (kind === 'sf');
  const S = isSF ? 0.88 : 1.0;
  const rC = isSF ? 1.70 * S : 0.36;
  const rH = isSF ? 1.20 * S : 0.24;            // axial and equatorial H: SAME van der Waals radius
  const colA = isSF ? 0xB8352A : 0xC0392B;
  const geoC = new THREE.SphereGeometry(rC, 48, 32);
  const geoH = new THREE.SphereGeometry(rH, 40, 28);

  const root = new THREE.Group();
  scene.add(root);
  const entries = [], carbons = [], hGroups = [];

  for (let i = 0; i < 6; i++) {
    const th = (-30 + 60 * i) * DEG;
    const s = (i % 2 === 0) ? 1 : -1;                      // pucker: even up, odd down
    const cp = new THREE.Vector3(RING_R * Math.cos(th), s * PUCK, RING_R * Math.sin(th)).multiplyScalar(S);

    const cm = new THREE.Mesh(geoC, atomMat(COL_C, true));
    cm.position.copy(cp);
    root.add(cm);
    const cEntry = { mesh: cm, mat: cm.material, kind: 'C', ci: i, base: COL_C };
    cm.userData.entry = cEntry; entries.push(cEntry);
    carbons.push({ i, pos: cp, s, th, mesh: cm });

    const aDir = new THREE.Vector3(0, s, 0);
    const eDir = new THREE.Vector3(
      Math.cos(th) * Math.cos(EQ_TILT), -s * Math.sin(EQ_TILT), Math.sin(th) * Math.cos(EQ_TILT)
    ).normalize();

    [['axial', aDir, colA], ['eq', eDir, COL_EQ]].forEach(([hk, dir, col]) => {
      const g = new THREE.Group();
      g.position.copy(cp);
      root.add(g);
      const hp = dir.clone().multiplyScalar(CH * S);
      const hm = new THREE.Mesh(geoH, atomMat(col, false));
      hm.position.copy(hp);
      g.add(hm);
      const hEntry = { mesh: hm, mat: hm.material, kind: hk, ci: i, base: col };
      hm.userData.entry = hEntry; entries.push(hEntry);
      if (!isSF) {
        const rod = makeRod(new THREE.Vector3(0, 0, 0), hp.clone(), 0.075, COL_ROD);
        g.add(rod);
        entries.push({ mesh: rod, mat: rod.material, kind: hk, ci: i, isRod: true, base: COL_ROD });
      }
      hGroups.push({ group: g, kind: hk, ci: i });
    });
  }

  if (!isSF) {
    for (let i = 0; i < 6; i++) {
      const a = carbons[i].pos, b = carbons[(i + 1) % 6].pos;
      const rod = makeRod(a.clone(), b.clone(), 0.085, COL_ROD);
      root.add(rod);
      entries.push({ mesh: rod, mat: rod.material, kind: 'bond', ci: [i, (i + 1) % 6], isRod: true, base: COL_ROD });
    }
  }

  const annot = new THREE.Group();
  root.add(annot);

  const aS = isSF ? 1.0 : 0.86;                 // callouts shrink with the smaller model
  return {
    kind, S, rC, rH, root, entries, carbons, hGroups, annot,
    annScale: aS,
    annLeft: -5.15 * aS, annTop: 4.85 * aS,
    arrowA: null, arrowE: null, annEntries: [],
    anchorA: sp(0, 0), anchorE: sp(0, 0),
    presence: 0, presenceT: 0, scale: 1, x: 0, xT: 0
  };
}

const sf = buildModel('sf');
const bs = buildModel('bs');
const models = [sf, bs];

/* ── state ────────────────────────────────────────────────────────────────── */
let modelMode = 'both';        // 'sf' | 'bs' | 'both'   (source figure = both panels)
let hFilter = 'both';          // 'ax' | 'eq' | 'both'
let axT = 1, eqT = 1, axFade = 1, eqFade = 1;
let selected = null;

/* initial pose so scene bounds are right when the camera is first fitted */
sf.presence = sf.presenceT = 1; sf.x = sf.xT = -PANEL_X;
bs.presence = bs.presenceT = 1; bs.x = bs.xT = PANEL_X;
sf.root.position.x = sf.x;
bs.root.position.x = bs.x;

/* ── camera (after geometry, before callouts) ─────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 90, elevationDeg: 88.5, rollDeg: 0,
  heightFraction: 0.65,
  target: [0, 0, 0]
});
camera.near = 0.5; camera.far = 500; camera.updateProjectionMatrix();
document.getElementById('btnReset').style.display = '';

/* ── framing that follows the current panel layout ────────────────────────── */
const camTargetT = new THREE.Vector3(0, 0, 0);
let camDistT = camera.position.distanceTo(controls.target);
let camAnim = false;

function layoutBox() {
  const both = (modelMode === 'both');
  const items = [];
  if (modelMode === 'sf' || both) items.push({ m: sf, x: both ? -PANEL_X : 0, ext: SF_EXT });
  if (modelMode === 'bs' || both) items.push({ m: bs, x: both ? PANEL_X : 0, ext: BS_EXT });
  if (!items.length) items.push({ m: sf, x: 0, ext: SF_EXT });
  const ann = items[0];
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const it of items) {
    minX = Math.min(minX, it.x - it.ext); maxX = Math.max(maxX, it.x + it.ext);
    minY = Math.min(minY, -it.ext); maxY = Math.max(maxY, it.ext);
  }
  minX = Math.min(minX, ann.x + ann.m.annLeft);
  maxY = Math.max(maxY, ann.m.annTop);
  return { cx: (minX + maxX) / 2, cy: (minY + maxY) / 2, hw: (maxX - minX) / 2, hh: (maxY - minY) / 2 };
}

function applyFit(instant) {
  const b = layoutBox();
  const el = renderer.domElement;
  const asp = Math.max(0.25, (el.clientWidth || 1) / (el.clientHeight || 1));
  const tv = Math.tan(THREE.MathUtils.degToRad((camera.fov || 35) / 2));
  const fill = 0.95;
  const dH = b.hh / tv / fill;
  const dW = b.hw / (tv * asp) / fill;
  camDistT = Math.max(6, Math.max(dH, dW));
  camTargetT.set(b.cx, 0, -b.cy);
  camAnim = true;
  if (instant) {
    controls.target.copy(camTargetT);
    const dir = camera.position.clone().sub(controls.target);
    if (dir.lengthSq() < 1e-6) dir.set(0, 1, 0.03);
    dir.normalize();
    camera.position.copy(controls.target).addScaledVector(dir, camDistT);
    controls.update();
    camAnim = false;
  }
}

function setModel(m) {
  modelMode = m;
  const side = (m === 'both');
  sf.presenceT = (m === 'sf' || side) ? 1 : 0;
  bs.presenceT = (m === 'bs' || side) ? 1 : 0;
  sf.xT = side ? -PANEL_X : 0;
  bs.xT = side ? PANEL_X : 0;
  applyFit(false);
  syncButtons();
}
function setFilter(f) {
  hFilter = f;
  axT = (f === 'eq') ? 0 : 1;
  eqT = (f === 'ax') ? 0 : 1;
  syncButtons();
}

applyFit(true);

/* ── callout arrows (need the camera, so built after framing) ─────────────── */
function arrowFromScreenTail(tailSx, tailSy, tip3d, bulge, color) {
  const tail = sp(tailSx, tailSy);
  const tipSx = tip3d.x, tipSy = -tip3d.z;
  const dx = tipSx - tailSx, dy = tipSy - tailSy;
  const L = Math.hypot(dx, dy) || 1;
  const px = -dy / L, py = dx / L;
  const ctrl = sp((tailSx + tipSx) / 2 + px * bulge, (tailSy + tipSy) / 2 + py * bulge);
  return makeArrow(tail, ctrl, tip3d, color);
}

function buildAnnotations(m) {
  // dispose any previous arrows so a re-fit can re-aim them exactly
  for (let i = m.annot.children.length - 1; i >= 0; i--) {
    const g = m.annot.children[i];
    g.traverse(o => { o.geometry?.dispose?.(); });
    m.annot.remove(g);
  }
  const S = m.S, a = m.annScale;

  // AXIAL target: carbon 4 (upper-left on screen), axial H pointing toward the viewer.
  const c4 = m.carbons[4];
  const aC = c4.pos.clone().add(new THREE.Vector3(0, c4.s * CH * S, 0));
  const nA = new THREE.Vector3(-0.60, 0.50, -0.60).normalize();
  const tipA = toFrontPlane(aC.clone().addScaledVector(nA, m.rH * 0.99));
  const arrowA = arrowFromScreenTail(-3.60 * a, 2.30 * a, tipA, 0.45, MAGENTA);

  // EQUATORIAL target: carbon 5 — its equatorial H is the TOP blue sphere on the rim.
  const c5 = m.carbons[5];
  const eD5 = new THREE.Vector3(
    Math.cos(c5.th) * Math.cos(EQ_TILT), -c5.s * Math.sin(EQ_TILT), Math.sin(c5.th) * Math.cos(EQ_TILT)
  ).normalize();
  const eC = c5.pos.clone().addScaledVector(eD5, CH * S);
  const nE = new THREE.Vector3(-0.50, 0.45, -0.74).normalize();
  const tipE = toFrontPlane(eC.clone().addScaledVector(nE, m.rH * 0.99));
  const arrowE = arrowFromScreenTail(-2.85 * a, 4.15 * a, tipE, 0.50, BLUEARR);

  m.annot.add(arrowA); m.annot.add(arrowE);
  m.arrowA = arrowA; m.arrowE = arrowE;
  m.anchorA = sp(-4.45 * a, 2.55 * a);
  m.anchorE = sp(-3.95 * a, 4.45 * a);

  m.annEntries = [];
  arrowA.userData.parts.forEach(p => { const e = { mesh: p, kind: 'annA' }; p.userData.entry = e; m.annEntries.push(e); });
  arrowE.userData.parts.forEach(p => { const e = { mesh: p, kind: 'annE' }; p.userData.entry = e; m.annEntries.push(e); });
}
buildAnnotations(sf);
buildAnnotations(bs);

let annDist = camera.position.distanceTo(controls.target);
const annDir = camera.position.clone().sub(controls.target).normalize();
function maybeRebuildAnnotations() {
  const dist = camera.position.distanceTo(controls.target);
  const dir = camera.position.clone().sub(controls.target).normalize();
  if (Math.abs(dist - annDist) > 0.3 || dir.dot(annDir) < 0.9992) {
    buildAnnotations(sf); buildAnnotations(bs);
    annDist = dist; annDir.copy(dir);
  }
}

/* ── labels ───────────────────────────────────────────────────────────────── */
const labEq = addLabel('Equatorial', new THREE.Vector3(0, 0, 0), { color: '#1C9AD6', fontSize: '16px' });
const labAx = addLabel('Axial', new THREE.Vector3(0, 0, 0), { color: '#E0218A', fontSize: '16px' });

function placeLabel(entry, model, anchor, visible, px) {
  entry.pos.set(anchor.x + model.x, anchor.y, anchor.z);
  entry.div.style.visibility = visible ? 'visible' : 'hidden';
  const dist = Math.max(camera.position.distanceTo(entry.pos), 1e-3);
  const s = Math.max(0.15, Math.min(6, 8 / dist));
  const fs = Math.round(px / s);
  if (entry.div.__fs !== fs) { entry.div.style.fontSize = fs + 'px'; entry.div.__fs = fs; }
}

/* ── picking (hover + click select) ───────────────────────────────────────── */
const pickRay = new THREE.Raycaster();
const pickPt = new THREE.Vector2();
const _tmp = new THREE.Vector3();
function pickEntry(ev) {
  const r = renderer.domElement.getBoundingClientRect();
  pickPt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  pickPt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  pickRay.setFromCamera(pickPt, camera);
  const targets = [];
  for (const m of models) {
    if (m.presence < 0.5) continue;
    if (m.annot.visible) for (const e of m.annEntries) targets.push(e.mesh);
    for (const e of m.entries) {
      if (e.isRod) continue;
      if (e.kind === 'axial' && axFade < 0.35) continue;
      if (e.kind === 'eq' && eqFade < 0.35) continue;
      targets.push(e.mesh);
    }
  }
  if (!targets.length) return null;
  const hits = pickRay.intersectObjects(targets, false);
  return hits.length ? hits[0].object.userData.entry : null;
}
function entryText(e) {
  if (e.kind === 'annA') return 'Axial position — parallel to the ring axis';
  if (e.kind === 'annE') return 'Equatorial position — out around the ring belt';
  const n = e.ci + 1;
  if (e.kind === 'C') return 'Ring carbon C' + n + ' — click to highlight its H pair';
  if (e.kind === 'axial') return 'Axial H on C' + n + ' — parallel to the ring axis';
  return 'Equatorial H on C' + n + ' — splayed out around the belt';
}
const selInfo = document.getElementById('selInfo');
function applySelection(ci) {
  selected = ci;
  if (ci === null) {
    selInfo.textContent = 'None — click any atom in the figure to light up one carbon together with its own axial (red) and equatorial (blue) hydrogen.';
  } else {
    const up = (ci % 2 === 0);
    selInfo.innerHTML = '<b>C' + (ci + 1) + '</b> (' + (up ? 'up-puckered' : 'down-puckered') +
      '): its axial H points ' + (up ? 'up, toward you' : 'down, away from you') +
      ', its equatorial H splays outward and tilts slightly ' + (up ? 'down' : 'up') +
      '. The same carbon is highlighted in <i>both</i> models.';
  }
}
renderer.domElement.addEventListener('pointermove', (ev) => {
  const e = pickEntry(ev);
  if (e) { renderer.domElement.style.cursor = 'pointer'; showTooltip(entryText(e), ev); }
  else { renderer.domElement.style.cursor = 'grab'; hideTooltip(); }
});
renderer.domElement.addEventListener('click', (ev) => {
  const e = pickEntry(ev);
  if (!e) { applySelection(null); hidePopup(); return; }
  if (e.kind === 'annA') {
    showPopup('Axial hydrogens',
      'The six axial C–H bonds run exactly parallel to the ring\'s three-fold axis — the direction you are looking down. Three point up out of the page and three point down behind it, alternating carbon by carbon. In the space-filling model they read as the red spheres crowded toward the centre of the disc.');
    return;
  }
  if (e.kind === 'annE') {
    showPopup('Equatorial hydrogens',
      'The six equatorial C–H bonds point outward around the belt of the ring, tilted only about 19.5° away from the mean plane — up on the down-puckered carbons and down on the up-puckered ones. They form the big blue rim of the space-filling disc.');
    return;
  }
  applySelection(e.ci);
  const up = (e.ci % 2 === 0);
  showPopup('Carbon C' + (e.ci + 1) + ': one axial + one equatorial H',
    'This ring carbon is ' + (up ? 'puckered up' : 'puckered down') + '. Its red axial hydrogen runs exactly parallel to the ring axis (' +
    (up ? 'upward' : 'downward') + '), while its blue equatorial hydrogen points outward around the ring belt, tilted about 19.5° ' +
    (up ? 'downward' : 'upward') + '. Every one of the six carbons carries exactly one of each — so each face of the chair bears three axial and three equatorial hydrogens, alternating.');
});
document.getElementById('clearSel').addEventListener('click', () => { applySelection(null); hidePopup(); });
document.getElementById('btnReset').addEventListener('click', () => { applyFit(false); });
window.addEventListener('resize', () => { setTimeout(() => applyFit(false), 0); });

/* ── per-frame state update ───────────────────────────────────────────────── */
function related(e, sel) {
  if (sel === null) return true;
  return Array.isArray(e.ci) ? e.ci.indexOf(sel) >= 0 : e.ci === sel;
}
function updateState(instant) {
  const k = instant ? 1 : 0.13;
  axFade += (axT - axFade) * k;
  eqFade += (eqT - eqFade) * k;

  for (const m of models) {
    m.presence += (m.presenceT - m.presence) * k;
    m.x += (m.xT - m.x) * k;
    m.root.position.x = m.x;
    m.root.visible = m.presence > 0.012;

    for (const hg of m.hGroups) {
      const f = (hg.kind === 'axial') ? axFade : eqFade;
      hg.group.scale.setScalar(Math.max(0.0001, f));
    }
    for (const e of m.entries) {
      const f = (e.kind === 'axial') ? axFade : (e.kind === 'eq') ? eqFade : 1;
      const dim = related(e, selected) ? 1 : 0.35;
      const o = m.presence * f * dim;
      const mat = e.mat;
      mat.opacity = o;
      const tr = o < 0.995;
      if (mat.transparent !== tr) { mat.transparent = tr; mat.needsUpdate = true; }
      mat.depthWrite = o > 0.55;
      if (mat.emissive) {
        const hot = (selected !== null) && related(e, selected) && !e.isRod;
        if (hot) { mat.emissive.setHex(e.base); mat.emissiveIntensity = 0.42; }
        else { mat.emissive.setHex(0x000000); mat.emissiveIntensity = 1; }
      }
    }
  }

  // camera framing tween (panel layout changes / reset / resize)
  if (camAnim) {
    controls.target.lerp(camTargetT, k);
    const dir = camera.position.clone().sub(controls.target);
    if (dir.lengthSq() < 1e-8) dir.set(0, 1, 0.03);
    dir.normalize();
    const curD = camera.position.distanceTo(controls.target);
    const nd = curD + (camDistT - curD) * k;
    camera.position.copy(controls.target).addScaledVector(dir, nd);
    if (Math.abs(nd - camDistT) < 0.02 && controls.target.distanceTo(camTargetT) < 0.02) {
      controls.target.copy(camTargetT);
      camera.position.copy(controls.target).addScaledVector(dir, camDistT);
      camAnim = false;
    }
  }
  maybeRebuildAnnotations();

  // callouts follow the leftmost visible model and fade out when tilted away
  const annModel = (sf.presence > 0.5) ? sf : bs;
  _tmp.copy(camera.position).sub(controls.target).normalize();
  const tilt = Math.acos(Math.min(1, Math.abs(_tmp.y))) / DEG;
  const show = tilt < 35;
  for (const m of models) {
    const on = (m === annModel) && show && m.presence > 0.5;
    m.annot.visible = on;
    if (m.arrowA) m.arrowA.visible = on && axT > 0.5;
    if (m.arrowE) m.arrowE.visible = on && eqT > 0.5;
  }
  placeLabel(labAx, annModel, annModel.anchorA, show && annModel.presence > 0.5 && axT > 0.5, 16);
  placeLabel(labEq, annModel, annModel.anchorE, show && annModel.presence > 0.5 && eqT > 0.5, 16);
}

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const modelBtns = Array.from(document.querySelectorAll('#modelBtns button'));
const hBtns = Array.from(document.querySelectorAll('#hBtns button'));
